public void testSecureZooKeeper() {
    // Setup for secure ZooKeeper configuration
    System.setProperty("zookeeper.server.secure", "true");
    // Start ZooKeeper server with security
    startSecureZooKeeperServer();
    // Execute tests that require secure ZooKeeper
    assertTrue(runSecureTests());
}

@Test
public void testNonSecureZooKeeper() {
    // Setup for non-secure ZooKeeper configuration
    System.setProperty("zookeeper.server.secure", "false");
    // Start ZooKeeper server without security
    startNonSecureZooKeeperServer();
    // Execute tests that require non-secure ZooKeeper
    assertTrue(runNonSecureTests());
}
